package ch.local.autoscroll;
import android.app.*;import android.os.*;import android.content.*;import android.provider.Settings;import android.widget.*;import android.view.*;
public class MainActivity extends Activity {
 LinearLayout l; SharedPreferences p; TextView diagnostic; final Handler handler=new Handler(Looper.getMainLooper()); final Runnable refresh=new Runnable(){public void run(){if(diagnostic!=null)diagnostic.setText("Service: "+(ScrollService.connected?"connected":"not connected")+"\nLast window: "+ScrollService.lastPackage+"\nRicardo detected: "+ScrollService.detected+"\nOverlay: "+ScrollService.overlayState);handler.postDelayed(this,500);}}; @Override protected void onResume(){super.onResume();handler.post(refresh);} @Override protected void onPause(){handler.removeCallbacks(refresh);super.onPause();}
 void choice(String label,String key,String[] vals,int def){TextView t=new TextView(this);t.setText(label);l.addView(t);Spinner s=new Spinner(this);s.setAdapter(new ArrayAdapter<String>(this,android.R.layout.simple_spinner_dropdown_item,vals));s.setSelection(p.getInt(key,def));l.addView(s);s.setOnItemSelectedListener(new AdapterView.OnItemSelectedListener(){public void onNothingSelected(AdapterView<?> a){} public void onItemSelected(AdapterView<?> a,View v,int i,long id){p.edit().putInt(key,i).apply();}});}
 public void onCreate(Bundle b){super.onCreate(b);p=getSharedPreferences("cfg",0);ScrollView sc=new ScrollView(this);l=new LinearLayout(this);l.setOrientation(LinearLayout.VERTICAL);l.setPadding(32,32,32,32);sc.addView(l);setContentView(sc);sc.setOnApplyWindowInsetsListener((v,i)->{if(Build.VERSION.SDK_INT>=30){android.graphics.Insets a=i.getInsets(WindowInsets.Type.systemBars());v.setPadding(a.left,a.top,a.right,a.bottom);}return i;});TextView title=new TextView(this);title.setText("Ricardo AutoScroll v2.1");title.setTextSize(26);l.addView(title);diagnostic=new TextView(this);l.addView(diagnostic);choice("Mode","mode",new String[]{"Étapes","Continu"},0);choice("Durée (s)","duration",new String[]{"30","60","90","120","180"},2);choice("Glissement (ms)","speed",new String[]{"600","800","1000","1500"},1);choice("Pause (s)","pause",new String[]{"1.5","2.5","4","6"},1);choice("Chevauchement cible (%)","overlap",new String[]{"15","20","25"},1);choice("Compte à rebours (s)","count",new String[]{"3","5","10"},1);TextView info=new TextView(this);info.setText("Active le service, ouvre les résultats Ricardo, lance l'enregistreur Samsung puis touche Start.");l.addView(info);Button btn=new Button(this);btn.setText("Paramètres d’accessibilité");btn.setOnClickListener(v->startActivity(new Intent(Settings.ACTION_ACCESSIBILITY_SETTINGS)));l.addView(btn);}
}